import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { startLiveBot } from "../services/api";

const LiveMeetingBot = () => {
  const [link, setLink] = useState("");
  const [botJoined, setBotJoined] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const handler = async (event) => {
      const audioBlob = event.detail.audio;
      const formData = new FormData();
      formData.append("audio", audioBlob);

      const res = await axios.post(
        "http://localhost:5000/api/livebot/end",
        formData
      );

      navigate("/result", { state: res.data });
    };

    window.addEventListener("meeting-ended", handler);
    return () => window.removeEventListener("meeting-ended", handler);
  }, [navigate]);

  const startBot = async () => {
    await startLiveBot({ meetingLink: link });
    setBotJoined(true);
    window.postMessage({ type: "START_RECORDING" }, "*");
  };

  return (
    <div>
      <input
        value={link}
        onChange={e => setLink(e.target.value)}
        placeholder="Paste meeting link"
      />
      <button onClick={startBot} disabled={botJoined}>
        Start Meeting Bot
      </button>
      {botJoined && <p>🤖 Bot joined, recording...</p>}
    </div>
  );
};

export default LiveMeetingBot;
